// IsPalindrome checks if a given string is a palindrome, ignoring case and non-alphanumeric characters.
func IsPalindrome(s string) bool {
	var clean strings.Builder
	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			clean.WriteRune(unicode.ToLower(r))
		}
	}
	cleaned := clean.String()
	for i, j := 0, len(cleaned)-1; i < j; i, j = i+1, j-1 {
		if cleaned[i] != cleaned[j] {
			return false
		}
	}
	return true
}

// TestIsPalindrome tests the IsPalindrome function with various cases.
func TestIsPalindrome(t *testing.T) {
	testCases := []struct {
		input    string
		expected bool
	}{
		{"A man, a plan, a canal: Panama", true},
		{"race a car", false},
		{" ", true},
		{"No lemon, no melon", true},
		{"Was it a car or a cat I saw?", true},
		{"Not a palindrome", false},
	}

	for _, tc := range testCases {
		t.Run(fmt.Sprintf("Input: %s", tc.input), func(t *testing.T) {
			result := IsPalindrome(tc.input)
			if result != tc.expected {
				t.Errorf("IsPalindrome(%q) = %v; want %v", tc.input, result, tc.expected)
			}
		})
	}
}

