type Counter struct {
	mu    sync.Mutex
	count map[string]int
}

func NewCounter() *Counter {
	return &Counter{
		count: make(map[string]int),
	}
}

func (c *Counter) Inc(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.count[key]++
}

func (c *Counter) Get(key string) int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.count[key]
}

