func TestMax(t *testing.T) {
	testCases := []struct {
		name     string
		input    []any
		expected any
	}{
		{"empty int slice", []any{}, 0, false},
		{"single int", []any{5}, 5, true},
		{"int slice with max at start", []any{10, 2, 3}, 10, true},
		{"int slice with max in middle", []any{1, 9, 3}, 9, true},
		{"int slice with max at end", []any{1, 2, 8}, 8, true},
		{"empty int64 slice", []any{}, int64(0), false},
		{"single int64", []any{int64(5)}, int64(5), true},
		{"int64 slice with max at start", []any{int64(10), int64(2), int64(3)}, int64(10), true},
		{"int64 slice with max in middle", []any{int64(1), int64(9), int64(3)}, int64(9), true},
		{"int64 slice with max at end", []any{int64(1), int64(2), int64(8)}, int64(8), true},
		{"empty float64 slice", []any{}, 0.0, false},
		{"single float64", []any{float64(5)}, 5.0, true},
		{"float64 slice with max at start", []any{float64(10), float64(2), float64(3)}, 10.0, true},
		{"float64 slice with max in middle", []any{float64(1), float64(9), float64(3)}, 9.0, true},
		{"float64 slice with max at end", []any{float64(1), float64(2), float64(8)}, 8.0, true},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			var result any
			var ok bool
			switch v := tc.input[0].(type) {
			case int:
				result, ok = Max[int](v.(int))
			case int64:
				result, ok = Max[int64](v.(int64))
			case float64:
				result, ok = Max[float64](v.(float64))
			default:
				t.Errorf("unsupported type: %T", v)
			}
			if !ok && tc.expected != nil {
				t.Errorf("expected max to be %v, got empty result", tc.expected)
			} else if ok && result != tc.expected {
				t.Errorf("expected max to be %v, got %v", tc.expected, result)
			}
		})
	}
}

