// TopK returns the k most frequent whitespace-separated words from the input string s.
// Words are returned in descending order of frequency, and in ascending alphabetical order for ties.
func TopK(s string, k int) []string {
	wordCount := make(map[string]int)
	for _, word := range strings.Fields(s) {
		wordCount[word]++
	}

	type wordFreq struct {
		word string
		freq int
	}
	var freqList []wordFreq
	for word, freq := range wordCount {
		freqList = append(freqList, wordFreq{word, freq})
	}

	sort.Slice(freqList, func(i, j int) bool {
		if freqList[i].freq == freqList[j].freq {
			return freqList[i].word < freqList[j].word
		}
		return freqList[i].freq > freqList[j].freq
	})

	var result []string
	for i := 0; i < k && i < len(freqList); i++ {
		result = append(result, freqList[i].word)
	}

	return result
}

