		{"one two three two one one", 1, []string{"one"}},
		{"", 0, []string{}},
	}

	for _, tc := range testCases {
		result := TopK(tc.s, tc.k)
		if !slicesEqual(result, tc.expect) {
			t.Errorf("TopK(%q, %d) = %v; want %v", tc.s, tc.k, result, tc.expect)
		}
	}
}

