// IntHeap is a min-heap of ints.
type IntHeap []int

func (h IntHeap) Len() int           { return len(h) }
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h IntHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *IntHeap) Push(x interface{}) {
	*h = append(*h, x.(int))
}

func (h *IntHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

// PopAllSorted pops all values from the heap in ascending order.
func PopAllSorted(vals []int) []int {
	h := &IntHeap{}
	heap.Init(h)
	for _, val := range vals {
		heap.Push(h, val)
	}
	var result []int
	for h.Len() > 0 {
		result = append(result, heap.Pop(h).(int))
	}
	return result
}

// TestPopAllSorted tests the PopAllSorted function.
func TestPopAllSorted(t *testing.T) {
	testCases := []struct {
		input    []int
		expected []int
	}{
		{[]int{3, 1, 4, 1, 5, 9}, []int{1, 1, 3, 4, 5, 9}},
		{[]int{}, []int{}},
		{[]int{7}, []int{7}},
		{[]int{2, 2, 2}, []int{2, 2, 2}},
	}

	for _, tc := range testCases {
		result := PopAllSorted(tc.input)
		for i, v := range result {
			if v != tc.expected[i] {
				t.Errorf("PopAllSorted(%v) = %v; want %v", tc.input, result, tc.expected)
				break
			}
		}
	}
}

