// Filter returns a new slice containing only the elements of s for which keep returns true.
func Filter[T any](s []T, keep func(T) bool) []T {
	var result []T
	for _, v := range s {
		if keep(v) {
			result = append(result, v)
		}
	}
	return result
}

// TestFilter tests the Filter function with various data points.
func TestFilter(t *testing.T) {
	testCases := []struct {
		name     string
		input    []int
		keepFunc func(int) bool
		expected []int
	}{
		{
			name:     "empty slice",
			input:    []int{},
			keepFunc: func(i int) bool { return i > 0 },
			expected: []int{},
		},
		{
			name:     "all elements pass",
			input:    []int{1, 2, 3, 4},
			keepFunc: func(i int) bool { return true },
			expected: []int{1, 2, 3, 4},
		},
		{
			name:     "all elements fail",
			input:    []int{1, 2, 3, 4},
			keepFunc: func(i int) bool { return false },
			expected: []int{},
		},
		{
			name:     "mixed pass and fail",
			input:    []int{1, 2, 3, 4},
			keepFunc: func(i int) bool { return i%2 == 0 },
			expected: []int{2, 4},
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			result := Filter(tc.input, tc.keepFunc)
			if !slicesEqual(result, tc.expected) {
				t.Errorf("Filter(%v, %v) = %v; want %v", tc.input, tc.keepFunc, result, tc.expected)
			}
		})
	}
}

// slicesEqual checks if two slices are equal.
func slicesEqual[T any](a, b []T) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

