import (
	"net/http"
	"testing"
)

// Chain applies middlewares to an HTTP handler.
// The first middleware in the list is applied last (outermost).
func Chain(h http.Handler, mws ...func(http.Handler) http.Handler) http.Handler {
	for i := len(mws) - 1; i >= 0; i-- {
		h = mws[i](h)
	}
	return h
}

// TestChain verifies the functionality of the Chain function.
func TestChain(t *testing.T) {
	testHandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("Hello, World!"))
	})

	middleware1 := func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Write([]byte("Middleware 1: "))
			next.ServeHTTP(w, r)
		})
	}

	middleware2 := func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Write([]byte("Middleware 2: "))
			next.ServeHTTP(w, r)
		})
	}

	chainedHandler := Chain(testHandler, middleware1, middleware2)

	t.Run("Chain with two middlewares", func(t *testing.T) {
		resp := new(http.ResponseRecorder)
		req, _ := http.NewRequest("GET", "/", nil)
		chainedHandler.ServeHTTP(resp, req)
		expected := "Middleware 1: Middleware 2: Hello, World!"
		if resp.Body.String() != expected {
			t.Errorf("Expected %s, got %s", expected, resp.Body.String())
		}
	})

	t.Run("Chain with no middlewares", func(t *testing.T) {
		resp := new(http.ResponseRecorder)
		req, _ := http.NewRequest("GET", "/", nil)
		testHandler.ServeHTTP(resp, req)
		expected := "Hello, World!"
		if resp.Body.String() != expected {
			t.Errorf("Expected %s, got %s", expected, resp.Body.String())
		}
	})
}
